CONSULTANT_PARSE_REPAIR_LIMIT = 3
CONSULTANT_SEMANTIC_REPAIR_LIMIT = 3
CONSULTANT_INTERNAL_VALIDATION_ERROR_LIMIT = 3
CONSULTANT_LOAD_ACTION_LOOP_LIMIT = 6
CONSULTANT_LOAD_ERROR_LOOP_LIMIT = 3
CONSULTANT_ESTIMATED_CHARS_PER_TOKEN = 4
CONSULTANT_HISTORY_CHAR_BUDGET = (
    CONSULTANT_HISTORY_TOKEN_BUDGET * CONSULTANT_ESTIMATED_CHARS_PER_TOKEN
)
CONSULTANT_SKILL_CHAR_BUDGET = (
    CONSULTANT_SKILL_TOKEN_BUDGET * CONSULTANT_ESTIMATED_CHARS_PER_TOKEN
)
_CONSULTANT_TOKEN_ENCODER: Any = None
_CONSULTANT_TOKEN_ENCODER_READY = False


def _consultant_token_encoder() -> Any:
    """Load a reference tokenizer lazily; keep deployment fallback optional."""
    global _CONSULTANT_TOKEN_ENCODER, _CONSULTANT_TOKEN_ENCODER_READY
    if _CONSULTANT_TOKEN_ENCODER_READY:
        return _CONSULTANT_TOKEN_ENCODER
    _CONSULTANT_TOKEN_ENCODER_READY = True
    try:
        import tiktoken  # type: ignore

        _CONSULTANT_TOKEN_ENCODER = tiktoken.get_encoding("cl100k_base")
    except Exception:
        _CONSULTANT_TOKEN_ENCODER = None
    return _CONSULTANT_TOKEN_ENCODER


def _consultant_estimate_text_tokens(text: str) -> int:
    """Estimate tokens without assuming four characters per token.

    DeepSeek does not expose its tokenizer through this client.  ``cl100k`` is
    used as a stable reference when available; the fallback deliberately
    charges CJK characters much more heavily than ASCII text.
    """
    value = str(text or "")
    if not value:
        return 0
    encoder = _consultant_token_encoder()
    if encoder is not None:
        try:
            return len(encoder.encode(value, disallowed_special=()))
        except Exception:
            pass
    ascii_chars = 0
    cjk_chars = 0
    other_chars = 0
    for char in value:
        codepoint = ord(char)
        if codepoint < 128:
            ascii_chars += 1
        elif (
            0x3400 <= codepoint <= 0x9FFF
            or 0xF900 <= codepoint <= 0xFAFF
            or 0x3040 <= codepoint <= 0x30FF
            or 0xAC00 <= codepoint <= 0xD7AF
        ):
            cjk_chars += 1
        else:
            other_chars += 1
    return max(
        1,
        (ascii_chars + 2) // 3
        + (cjk_chars * 5 + 3) // 4
        + (other_chars + 1) // 2,
    )


def _consultant_tokenizer_name() -> str:
    return "cl100k_base_reference" if _consultant_token_encoder() is not None else "mixed_script_fallback"


def _is_deepseek_target(model: str, base_url: str) -> bool:
    return "deepseek" in str(base_url or "").lower() or str(
        model or ""
    ).lower().startswith("deepseek-")


def _llm_extra_body(model: str, base_url: str) -> dict[str, Any]:
    model_lower = (model or "").lower()
    base_url_lower = (base_url or "").lower()

    if _is_deepseek_target(model, base_url):
        # Thinking is node-scoped below.  Keep the shared client explicitly
        # non-thinking so Planner/Consultant/Supervisor do not inherit it.
        return {"thinking": {"type": "disabled"}}

    if "dashscope.aliyuncs.com" in base_url_lower or "qwen" in model_lower:
        return {"enable_thinking": False}

    return {}


def _bind_deepseek_thinking_llm(
    llm: Any,
    *,
    model: str,
    base_url: str,
    enabled: bool,
    reasoning_effort: str,
    scope: str,
) -> Tuple[Any, Dict[str, Any]]:
    """Bind DeepSeek thinking to one node without mutating the shared client."""
    is_deepseek = _is_deepseek_target(model, base_url)
    if not enabled or not is_deepseek or not hasattr(llm, "bind"):
        return llm, {
            "thinking_enabled": False,
            "thinking": {"type": "disabled"},
            "reasoning_effort": "",
            "scope": scope,
        }
    bound = llm.bind(
        extra_body={"thinking": {"type": "enabled"}},
        reasoning_effort=str(reasoning_effort or "high"),
        temperature=None,
    )
    return bound, {
        "thinking_enabled": True,
        "thinking": {"type": "enabled"},
        "reasoning_effort": str(reasoning_effort or "high"),
        "scope": scope,
    }


def bind_generate_llm(
    llm: Any,
    *,
    model: str,
    base_url: str,
    enabled: bool = GENERATE_THINKING_ENABLED,
    reasoning_effort: str = GENERATE_REASONING_EFFORT,
) -> Tuple[Any, Dict[str, Any]]:
    return _bind_deepseek_thinking_llm(
        llm,
        model=model,
        base_url=base_url,
        enabled=enabled,
        reasoning_effort=reasoning_effort,
        scope="generate_only",
    )


def generate_client_kwargs(shared_kwargs: Mapping[str, Any]) -> Dict[str, Any]:
    """Return the Generate-only transport policy with one retry owner."""

    result = dict(shared_kwargs)
    result["max_retries"] = 0
    # A normal-but-empty response is retried by the application budget, so it
    # must never enter LangChain's successful completion cache.
    result["cache"] = False
    return result


def planner_client_kwargs(shared_kwargs: Mapping[str, Any]) -> Dict[str, Any]:
    """One observable network attempt per charged Planner request; no SDK retry."""
    result = dict(shared_kwargs)
    result.update(max_retries=0, cache=False)
    return result


def recovery_client_kwargs(shared_kwargs: Mapping[str, Any]) -> Dict[str, Any]:
    """Return a Recovery transport with one observable network-attempt owner."""

    result = dict(shared_kwargs)
    result["max_retries"] = 0
    # A cache hit is not a network attempt and can obscure incident replay.
    # Recovery therefore keeps both SDK retry and completion-cache ownership
    # at the application boundary.
    result["cache"] = False
    return result


def _generate_requires_semantic_action_protocol(
    step: Mapping[str, Any],
    capability_contract: Mapping[str, Any],
) -> bool:
    """Keep typed binding candidates out of the script-only Generate ABI."""
    binding_applicability = capability_contract.get("binding_applicability")
    if (
        isinstance(binding_applicability, Mapping)
        and binding_applicability.get("applicable") is True
    ):
        return True
    raw_effect = step.get("step_effect")
    if not isinstance(raw_effect, Mapping):
        raw_effect = {
            "produces_bindings": deepcopy(
                step.get("produces_bindings") or []
            ),
        }
    effect = canonical_step_effect(raw_effect)
    return bool(effect.get("produces_bindings"))


def response_has_final_content(response: Any) -> bool:
    content = getattr(response, "content", "")
    if isinstance(content, str):
        return bool(content.strip())
    if isinstance(content, (list, tuple)):
        for item in content:
            value = (
                item.get("text") or item.get("content") or ""
                if isinstance(item, Mapping)
                else item
            )
            if str(value or "").strip():
                return True
        return False
    return bool(content)


